"use strict";
/* ===== quadratic helpers ===== */
function ts(list){let s='';list.forEach(([c,p])=>{c=Math.round(c*1e6)/1e6;if(!c)return;const ab=Math.abs(c);const v=p===0?'':p===1?'x':'x^'+p;s+=(c<0?(s?' - ':'-'):(s?' + ':''))+((ab===1&&p)?'':raw(ab))+v});return s||'0'}
function typeTags(a,b,c){const k=classify(a,b,c);if(k.kind==='quad')return`<span class="tag quad">${tx(U.quad)}</span><span class="tag neu">${tx(U[k.comp])}</span><span class="tag neu">${tx(U[k.monic?'monic':'nonmonic'])}</span>`;
  return`<span class="tag lin">${tx(k.kind==='linear'?U.linear:U.constant)}</span><span class="tag neu">${tx(L('not quadratic','квадрат емес','не квадратное'))}</span>`}
function reasons(a,b,c){const k=classify(a,b,c),r=[];const A='a = '+num(a),B='b = '+num(b),C='c = '+num(c);
  if(k.kind==='quad'){r.push(tx(L(`${A} ≠ 0 → highest power of x is 2: quadratic.`,`${A} ≠ 0 → x-тің ең жоғары дәрежесі 2: квадрат теңдеу.`,`${A} ≠ 0 → старшая степень x равна 2: квадратное.`)));
    r.push(tx({complete:L(`${B} ≠ 0, ${C} ≠ 0 → complete.`,`${B} ≠ 0, ${C} ≠ 0 → толық.`,`${B} ≠ 0, ${C} ≠ 0 → полное.`),bx:L(`${C} → incomplete ax² + bx = 0.`,`${C} → толымсыз ax² + bx = 0.`,`${C} → неполное ax² + bx = 0.`),c:L(`${B} → incomplete ax² + c = 0.`,`${B} → толымсыз ax² + c = 0.`,`${B} → неполное ax² + c = 0.`),zero:L(`${B}, ${C} → incomplete ax² = 0.`,`${B}, ${C} → толымсыз ax² = 0.`,`${B}, ${C} → неполное ax² = 0.`)}[k.comp]));
    r.push(k.monic?tx(L(`${A} → monic.`,`${A} → келтірілген.`,`${A} → приведённое.`)):tx(L(`${A} ≠ 1 → non-monic.`,`${A} ≠ 1 → келтірілмеген.`,`${A} ≠ 1 → неприведённое.`)))}
  else r.push(tx(L('a = 0: the x² term disappears, so the equation is not quadratic.','a = 0: x² мүшесі жойылады, теңдеу квадрат емес.','a = 0: член с x² исчезает, уравнение не квадратное.')));
  return`<ul class="reasons">${r.map(x=>`<li>${x}</li>`).join('')}</ul>`}
function stdEx(r){return r.ok&&r.deg<=2?M(ts([[r.a,2],[r.b,1],[r.c,0]])+' = 0'):''}
function quadPlot(P,a,b,c,extra={}){const pts=[];if(a){const D=b*b-4*a*c;if(D>=0){const s=Math.sqrt(D);[(-b-s)/(2*a),(-b+s)/(2*a)].forEach(x=>pts.push({x,y:0,cls:'p1'}))}const vx=-b/(2*a);pts.push({x:vx,y:a*vx*vx+b*vx+c,cls:'p2'})}else if(b)pts.push({x:-c/b,y:0,cls:'p1'});pts.push({x:0,y:c,cls:'p3'});P.draw(Object.assign({fns:[{f:x=>a*x*x+b*x+c}],pts},extra))}
const LEG=()=>`<div class="legend"><span style="--c:var(--kb)">${tx(U.roots)}</span><span style="--c:var(--ka)">${tx(U.vertex)}</span><span style="--c:var(--kc)">${tx(U.yint)}</span></div>`;
function makeEq(lv,r){/* returns equation string whose truth is checked by analyze() */
  const a=pick(r,[1,1,2,3,-1,-2,5]),b=nz(r,-7,7),c=nz(r,-9,9),p=nz(r,-5,5),q=nz(r,-9,9);
  if(lv===1)return pick(r,[ts([[a,2],[b,1],[c,0]])+' = 0',ts([[b,1],[c,0]])+' = 0',ts([[1,3],[b,1],[c,0]])+' = 0',ts([[c,0],[b,1],[a,2]])+' = 0',ts([[a,2],[c,0]])+' = 0']);
  if(lv===2)return pick(r,[ts([[a,2]])+' = '+ts([[b,1],[c,0]]),'x(x '+(p<0?'- '+(-p):'+ '+p)+') = '+q,ts([[c,0],[-1,2]])+' = 0',ts([[a,2],[b,1]])+' = '+ts([[a,2],[c,0]])]);
  return pick(r,['(x '+(p<0?'- '+(-p):'+ '+p)+')^2 = x^2 '+(q<0?'- '+(-q):'+ '+q),'2(x^2 '+(p<0?'- '+(-p):'+ '+p)+') = x^2','(x '+(p<0?'- '+(-p):'+ '+p)+')(x '+(q<0?'- '+(-q):'+ '+q)+') = 0',(a===1?'':a===-1?'-':a)+'(x^2 + '+Math.abs(p)+') = '+ts([[a,2],[1,1]])])}

